(assert (= "1.12.6" (clojure-version)))
(let [source "(let [x (* -0.0 1.0) y (+ 3000000000 5) f (fn [v] v)] (loop [i 0 out []] (if (< i 4) (let [a (f x) b (if (zero? (bit-and i 1)) (f y) (identity y))] (recur (inc i) (conj out [a b]))) [x y out])))" expected "[-0.0 3000000005 [[-0.0 3000000005] [-0.0 3000000005] [-0.0 3000000005] [-0.0 3000000005]]]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= actual expected)))
(let [source "(let [f (fn [v] v)] (loop [i 0 d 1.5 w 3000000000 out []] (if (< i 4) (let [a (f d) b (f w)] (recur (inc i) (+ d 0.5) (+ w 2) (conj out [a b]))) out)))" expected "[[1.5 3000000000] [2.0 3000000002] [2.5 3000000004] [3.0 3000000006]]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= actual expected)))
(let [source "(let [f (fn [v] v) x (+ 1.25 0.5)] [(if true (f x) :unused) (if false :unused (f x)) (f x) (identical? (f x) (f x))])" expected "[1.75 1.75 1.75 true]" actual (pr-str (eval (read-string source)))] (prn source actual) (assert (= actual expected)))
